local ServiceDescriptorResolver = require(script.Parent.ServiceDescriptorResolver)
local ServiceDescriptor = require(script.Parent.ServiceDescriptor)
local ServiceLifetime = require(script.Parent.ServiceLifetime)
local ServiceProvider = require(script.Parent.ServiceProvider)

return function()
	describe("ServiceDescriptorResolver", function()
		local mockServiceProvider
		local mockDescriptor
		local mockService

		beforeEach(function()
			mockServiceProvider = {
				IsRoot = true,
				TryGetCachedService = function(self, serviceType)
					return nil
				end,
				AddCache = function(self, serviceType, instance) end,
				AddCreatedObjectHistory = function(self, instance) end,
			}
			mockDescriptor = {
				Lifetime = ServiceLifetime.Transient,
				ImplementationInstance = nil,
				ImplementationFactory = nil,
				ImplementationType = nil,
			}
			mockService = "MockService"
		end)

		it("should resolve transient services without caching", function()
			mockDescriptor.ImplementationInstance = "TransientInstance"
			local result = ServiceDescriptorResolver.Resolve(mockServiceProvider, mockService, mockDescriptor, {})
			expect(result).to.equal("TransientInstance")
		end)

		it("should resolve singleton services using root provider", function()
			mockDescriptor.Lifetime = ServiceLifetime.Singleton
			mockDescriptor.ImplementationInstance = "SingletonInstance"

			local result = ServiceDescriptorResolver.Resolve(mockServiceProvider, mockService, mockDescriptor, {})
			expect(result).to.equal("SingletonInstance")
		end)

		it("should use implementation factory when provided", function()
			mockDescriptor.ImplementationFactory = function()
				return "FactoryResult"
			end

			local result = ServiceDescriptorResolver.Resolve(mockServiceProvider, mockService, mockDescriptor, {})
			expect(result).to.equal("FactoryResult")
		end)

		it("should throw an error when no implementation is provided", function()
			expect(function()
				ServiceDescriptorResolver.Resolve(mockServiceProvider, mockService, mockDescriptor, {})
			end).to.throw()
		end)
	end)
end
